def _apply(data, use_new_policy):
    result = []
    for lo, hi in sorted(data):
        if result:
            prev = result[-1]
            merge = lo <= prev[1] or (use_new_policy and lo == prev[1] + 1)
            if merge:
                if hi > prev[1]:
                    prev[1] = hi
                continue
        result.append([lo, hi])
    return result

def _summary(payload):
    return {'size': len(payload['data']), 'tag': payload.get('tag', '')}

def solve(payload):
    summary = _summary(payload)
    result = _apply(payload['data'], bool(payload.get('use_new_policy', False)))
    return {'result': result, 'summary': summary}

